"use client";
import { useState, useEffect } from "react";
import axios from "axios";
import Link from "next/link";
import { IconButton } from "@mui/material";
import { Edit as EditIcon, Delete as DeleteIcon, FileDownload as FileDownloadIcon } from "@mui/icons-material";
import Sidebar from "../components/sidebar";
import Navbar from "../components/Navbar";

export default function GestionGroupes() {
  const [groupes, setGroupes] = useState([]);
  const [tuteurs, setTuteurs] = useState([]);
  const [sujets, setSujets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState("table"); // 'table' ou 'card'
  const [showExportOptions, setShowExportOptions] = useState(false);
  const [currentPage, setCurrentPage] = useState(1); // Pagination
  const [itemsPerPage, setItemsPerPage] = useState(10); // Nombre d'éléments par page

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [groupesResponse, etudiantsResponse, tuteursResponse, sujetsResponse] = await Promise.all([
        axios.get("http://localhost:5000/api/groupes"),
        axios.get("http://localhost:5000/api/etudiants"),
        axios.get("http://localhost:5000/api/tuteurs"),
        axios.get("http://localhost:5000/api/sujets"),
      ]);

      if (!groupesResponse.data || !Array.isArray(groupesResponse.data)) {
        throw new Error("Format de données des groupes invalide");
      }

      const etudiantsMap = new Map();
      if (etudiantsResponse.data && Array.isArray(etudiantsResponse.data)) {
        etudiantsResponse.data.forEach((etudiant) => {
          if (etudiant && etudiant.idGroupe) {
            if (!etudiantsMap.has(etudiant.idGroupe)) {
              etudiantsMap.set(etudiant.idGroupe, []);
            }
            etudiantsMap.get(etudiant.idGroupe).push(`${etudiant.nom || ""} ${etudiant.prenom || ""}`);
          }
        });
      }

      const tuteursData = Array.isArray(tuteursResponse.data) ? tuteursResponse.data : [];
      const sujetsData = Array.isArray(sujetsResponse.data) ? sujetsResponse.data : [];

      const groupesData = groupesResponse.data.map((groupe) => {
        const tuteur = tuteursData.find((t) => t.idTuteur === groupe.idTuteur);
        const sujet = sujetsData.find((s) => s.idSujet === groupe.idSujet);
        return {
          ...groupe,
          etudiants: etudiantsMap.get(groupe.idGroupe) || [],
          tuteur: tuteur || null,
          sujet: sujet || null,
          isAffected: !!(tuteur && sujet),
        };
      });

      setGroupes(groupesData);
      setTuteurs(tuteursData);
      setSujets(sujetsData);
    } catch (error) {
      console.error("Erreur lors du chargement des données:", error);
      alert("Erreur lors du chargement des données");
    } finally {
      setLoading(false);
    }
  };

  const handleTuteurChange = (groupe, tuteurId) => {
    if (!tuteurId) return;
    const selectedTuteur = tuteurs.find((t) => t.idTuteur === tuteurId);
    if (!selectedTuteur) return;
    setGroupes((prevGroupes) =>
      prevGroupes.map((g) => {
        if (g.idGroupe === groupe.idGroupe) {
          return {
            ...g,
            tuteur: selectedTuteur,
            isAffected: false,
          };
        }
        return g;
      })
    );
  };

  const handleSujetChange = (groupe, sujetId) => {
    if (!sujetId) return;
    const selectedSujet = sujets.find((s) => s.idSujet === parseInt(sujetId));
    if (!selectedSujet) return;
    setGroupes((prevGroupes) =>
      prevGroupes.map((g) => {
        if (g.idGroupe === groupe.idGroupe) {
          return {
            ...g,
            sujet: selectedSujet,
            isAffected: false,
          };
        }
        return g;
      })
    );
  };

  const affecterGroupe = async () => {
    const groupesAAffecter = groupes.filter((groupe) => groupe.tuteur && groupe.sujet && !groupe.isAffected);
    if (groupesAAffecter.length === 0) {
      alert("Veuillez sélectionner un tuteur et un sujet pour au moins un groupe non affecté.");
      return;
    }
    try {
      for (const groupe of groupesAAffecter) {
        const response = await axios.post(
          `http://localhost:5000/api/affecterSujetsAuGroupe/${groupe.idGroupe}`,
          {
            idTuteur: groupe.tuteur.idTuteur,
            idSujet: groupe.sujet.idSujet,
          }
        );
        if (response.data && response.data.groupe) {
          setGroupes((prevGroupes) =>
            prevGroupes.map((g) =>
              g.idGroupe === groupe.idGroupe ? { ...g, isAffected: true } : g
            )
          );
        }
      }
      alert("Affectation réussie !");
      await fetchData();
    } catch (error) {
      console.error("Erreur détaillée:", error.response?.data || error.message);
      alert(`Erreur lors de l'affectation: ${error.response?.data?.message || "Erreur inconnue"}`);
    }
  };

  const deleteGroupe = async (idGroupe) => {
    if (!window.confirm("Voulez-vous vraiment supprimer cette affectation ?")) return;
    try {
      await axios.delete(`http://localhost:5000/api/supprimerAffectationsGroupe/${idGroupe}`);
      alert("Affectation supprimée avec succès");
      await fetchData();
    } catch (error) {
      console.error("Erreur lors de la suppression du groupe :", error);
      alert("Erreur lors de la suppression du groupe");
    }
  };

  const handleExport = (type) => {
    const exportUrl =
      type === "excel"
        ? "http://localhost:5000/api/excel"
        : "http://localhost:5000/api/word";

    // Téléchargement direct du fichier
    window.open(exportUrl, "_blank");

    // Fermer le menu d'options d'export
    setShowExportOptions(false);
  };

  // Pagination
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentGroupes = groupes.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(groupes.length / itemsPerPage);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  const handleItemsPerPageChange = (e) => {
    setItemsPerPage(Number(e.target.value));
    setCurrentPage(1);
  };

  // Rendu du tableau des groupes
  const renderTableView = () => (
    <div className="overflow-x-auto bg-white rounded-xl shadow-lg">
      <table className="min-w-full">
        <thead className="bg-gradient-to-r from-blue-500 to-blue-600 sticky top-0">
          <tr>
            <th className="p-4 text-left text-white">Nom du Groupe et Étudiants</th>
            <th className="p-4 text-left text-white">Tuteur</th>
            <th className="p-4 text-left text-white">Sujet</th>
            <th className="p-4 text-left text-white">Actions</th>
          </tr>
        </thead>
        <tbody>
          {currentGroupes.map((groupe, index) => (
            <tr
              key={groupe.idGroupe}
              className={`border-b border-gray-100 hover:bg-gray-50 transition ${
                index % 2 === 0 ? "bg-gray-50" : "bg-white"
              }`}
            >
              <td className="p-4 text-gray-800">
                <strong>{groupe.nomGroupe}</strong>
                <ul className="ml-4 list-disc">
                  {groupe.etudiants.map((etudiant, index) => (
                    <li key={index}>{etudiant}</li>
                  ))}
                </ul>
              </td>
              <td className="p-4 text-gray-800">
                {groupe.isAffected ? (
                  <span>{groupe.tuteur ? `${groupe.tuteur.nom} ${groupe.tuteur.prenom}` : "Non assigné"}</span>
                ) : (
                  <select
                    value={groupe.tuteur?.idTuteur || ""}
                    onChange={(e) => handleTuteurChange(groupe, e.target.value)}
                    className="border p-2 rounded w-full focus:outline-none focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="">Sélectionner un tuteur</option>
                    {tuteurs
                      .filter(
                        (tuteur) =>
                          !groupes.some(
                            (g) =>
                              g.idGroupe !== groupe.idGroupe &&
                              g.tuteur?.idTuteur === tuteur.idTuteur
                          )
                      )
                      .map((tuteur) => (
                        <option key={tuteur.idTuteur} value={tuteur.idTuteur}>
                          {tuteur.nom} {tuteur.prenom}
                        </option>
                      ))}
                  </select>
                )}
              </td>
              <td className="p-4 text-gray-800">
                {groupe.isAffected ? (
                  <span>{groupe.sujet ? groupe.sujet.titre : "Non assigné"}</span>
                ) : (
                  <select
                    value={groupe.sujet?.idSujet || ""}
                    onChange={(e) => handleSujetChange(groupe, e.target.value)}
                    className="border p-2 rounded w-full focus:outline-none focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="">Sélectionner un sujet</option>
                    {sujets
                      .filter((sujet) => {
                        const count = groupes.filter(
                          (g) =>
                            g.idGroupe !== groupe.idGroupe &&
                            g.sujet?.idSujet === sujet.idSujet
                        ).length;
                        return count < 3;
                      })
                      .map((sujet) => (
                        <option key={sujet.idSujet} value={sujet.idSujet}>
                          {sujet.titre}
                        </option>
                      ))}
                  </select>
                )}
              </td>
              <td className="p-4 text-center flex justify-center space-x-3">
                <Link href={`/users/editgrp/${groupe.idGroupe}`} passHref>
                  <IconButton color="primary" title="Éditer">
                    <EditIcon />
                  </IconButton>
                </Link>
                <IconButton
                  color="error"
                  onClick={() => deleteGroupe(groupe.idGroupe)}
                  title="Supprimer"
                >
                  <DeleteIcon />
                </IconButton>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Pagination */}
      <div className="flex justify-between items-center p-4 bg-gradient-to-r from-blue-50 to-gray-50">
        <select
          onChange={handleItemsPerPageChange}
          value={itemsPerPage}
          className="border p-2 rounded-lg shadow-sm"
        >
          <option value={10}>10 par page</option>
          <option value={20}>20 par page</option>
          <option value={50}>50 par page</option>
        </select>
        <div className="flex space-x-2">
          {Array.from({ length: totalPages }, (_, index) => (
            <button
              key={index}
              onClick={() => paginate(index + 1)}
              className={`px-4 py-2 text-sm rounded-lg ${
                currentPage === index + 1 ? "bg-blue-600 text-white" : "bg-white text-blue-600"
              }`}
            >
              {index + 1}
            </button>
          ))}
        </div>
      </div>
    </div>
  );

  // Rendu de la vue en cartes
  const renderCardView = () => (
    <div className="mt-4 space-y-6">
      {currentGroupes.map((groupe) => (
        <div
          key={groupe.idGroupe}
          className="bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow duration-300 p-6 border border-gray-200"
        >
          {/* Titre du groupe */}
          <h3 className="text-xl font-semibold text-blue-600 mb-4">
            Groupe : {groupe.nomGroupe}
          </h3>

          {/* Tuteur */}
          <div className="mb-4">
            <p className="text-sm text-gray-500 font-medium">Tuteur</p>
            <p className="text-lg text-gray-800">
              {groupe.tuteur ? `${groupe.tuteur.nom} ${groupe.tuteur.prenom}` : "Non assigné"}
            </p>
          </div>

          {/* Sujet */}
          <div className="mb-4">
            <p className="text-sm text-gray-500 font-medium">Sujet</p>
            <p className="text-lg text-gray-800">
              {groupe.sujet ? groupe.sujet.titre : "Non assigné"}
            </p>
          </div>

          {/* Étudiants */}
          <div>
            <p className="text-sm text-gray-500 font-medium">Étudiants</p>
            <ul className="mt-2 space-y-2">
              {groupe.etudiants.map((etudiant, index) => (
                <li key={index} className="text-gray-700">
                  <span className="text-blue-500 mr-2">•</span>
                  {etudiant}
                </li>
              ))}
            </ul>
          </div>

          {/* Statut d'affectation */}
          {groupe.isAffected && (
            <p className="text-green-600 font-semibold mt-4">✓ Affecté</p>
          )}
        </div>
      ))}

      {/* Pagination */}
      <div className="flex justify-between items-center mt-4 p-4 bg-white border-t border-gray-200">
        <select
          onChange={handleItemsPerPageChange}
          value={itemsPerPage}
          className="border p-2 rounded-lg shadow-sm"
        >
          <option value={10}>10 par page</option>
          <option value={20}>20 par page</option>
          <option value={50}>50 par page</option>
        </select>
        <div className="flex space-x-2">
          {Array.from({ length: totalPages }, (_, index) => (
            <button
              key={index}
              onClick={() => paginate(index + 1)}
              className={`px-4 py-2 text-sm rounded-lg ${
                currentPage === index + 1 ? "bg-blue-600 text-white" : "bg-white text-blue-600"
              }`}
            >
              {index + 1}
            </button>
          ))}
        </div>
      </div>
    </div>
  );

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Sidebar fixe */}
      <div className="fixed left-0 top-0 h-screen w-64 bg-blue-700 text-white shadow-lg">
        <Sidebar />
      </div>
      {/* Contenu principal avec marges pour la Sidebar et la Navbar */}
      <div className="flex flex-col w-full ml-64">
        {/* Navbar fixe */}
        <div className="fixed top-0 left-64 right-0 bg-blue-600 text-white shadow-md z-10">
          <Navbar />
        </div>
        {/* Barre d'affectation (séparée de la Navbar) */}
        <div className="mt-20 p-6">
          <div className="flex justify-between items-center">
            <h2 className="text-2xl font-bold text-blue-600">Affectation</h2>
            <div className="flex space-x-4">
              <button
                onClick={affecterGroupe}
                className="bg-blue-500 text-white px-6 py-2 rounded hover:bg-blue-600 transition-all"
              >
                Affecter
              </button>
              <button
                onClick={() => setViewMode(viewMode === "table" ? "card" : "table")}
                className="bg-green-500 text-white px-4 py-2 rounded hover:bg-green-600 transition-all"
              >
                {viewMode === "table" ? "Voir la liste" : "Cacher la liste"}
              </button>
              <div className="relative">
                <button
                  onClick={() => setShowExportOptions(!showExportOptions)}
                  className="bg-teal-500 text-white px-4 py-2 rounded flex items-center hover:bg-teal-600 transition-all"
                >
                  <FileDownloadIcon className="mr-1" />
                  Exporter
                </button>
                {showExportOptions && (
                  <div className="absolute right-0 mt-2 w-48 bg-white rounded shadow-lg z-10">
                    <button
                      onClick={() => handleExport("excel")}
                      className="block w-full text-left px-4 py-2 hover:bg-gray-100"
                    >
                      Exporter en Excel
                    </button>
                    <button
                      onClick={() => handleExport("word")}
                      className="block w-full text-left px-4 py-2 hover:bg-gray-100"
                    >
                      Exporter en Word
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
        {/* Contenu défilant */}
        <div className="mt-6 p-6 overflow-y-auto">
          {loading ? (
            <div className="flex justify-center items-center h-64">
              <div className="text-blue-500">Chargement des données...</div>
            </div>
          ) : viewMode === "table" ? (
            renderTableView()
          ) : (
            renderCardView()
          )}
        </div>
      </div>
    </div>
  );
}